ALIMENTOS_EXTRA: dict = {}
GRAMOS_EXTRA: dict = {}
SINONIMOS_EXTRA: dict = {}
NOMBRES_FR: dict = {}
for clave, es, fr, rac, g, kcal, p, h, gr, grupo, etq, sin in _D:
    k = g / 100
    ALIMENTOS_EXTRA[clave] = (es, rac, round(kcal * k), round(p * k), round(h * k), round(gr * k), grupo, tuple(etq))
    GRAMOS_EXTRA[clave] = g
    SINONIMOS_EXTRA[clave] = list(dict.fromkeys([es.lower(), fr.lower(), *[x.lower() for x in sin]]))
    NOMBRES_FR[es] = fr
